<body>

    <div class="crt-overlay"></div>

    <div class="mac-window">

        <div class="title-bar">
            <span class="window-title">文本4_文本5_文本6.文本7</span>
            <div class="close-btn-wrapper"><div class="close-btn">X</div></div>
        </div>

        <div class="window-content">

            <div class="tabs">
                <button class="tab-btn active" id="btn-readme" onclick="switchTab('readme')">文本8.文本9</button>
                <button class="tab-btn" id="btn-player" onclick="switchTab('player')">文本10</button>
                <button class="tab-btn" id="btn-levels" onclick="switchTab('levels')">文本11</button>
