                        <li>文本19 [ 文本11 ] 文本20</li>
                    </ul>
                </div>
                <div class="readme-footer">
                     TIP: 文本21
                </div>
                <button class="next-btn" onclick="switchTab('player')">> 文本22 <</button>
            </div>


            <div id="player" class="panel">
