                    <label>> 文本32 (文本31):</label>
                    <textarea id="user-persona" rows="2" placeholder="文本33"></textarea>
                </div>

                <div class="form-group">
                    <label style="color: #ff5555;">> 文本35 (文本34):</label>
                    <input type="text" id="user-lover" class="yandere-input" placeholder="???">
                </div>
                <button class="next-btn" onclick="confirmProfile()">>> 文本36 & 文本11</button>
            </div>


            <div id="levels" class="panel">
                 <div class="readme-header"><span class="readme-title">文本37</span></div>
                <p style="font-size: 12px; color: #888; text-align: center; margin-bottom: 20px;">文本38...</p>
                <div id="swipe-list-container">
                    <p style="animation: blink 1s infinite; text-align: center;">文本39...</p>
                </div>
            </div>
        </div>
    </div>

    <script>
        function switchTab(tabId) {
            document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
            document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
            document.getElementById(tabId).classList.add('active');
            document.getElementById('btn-' + tabId).classList.add('active');
            if (tabId === 'levels') loadSwipes();
        }

        function confirmProfile() {
            const nameInput = document.getElementById('user-name');
            const name = nameInput.value;


            if(!name) {
                const originalBorder = nameInput.style.borderColor;
                nameInput.style.borderColor = 'red';
                setTimeout(() => nameInput.style.borderColor = originalBorder, 500);
            }


            const personaInput = document.getElementById('user-persona');
            if (!personaInput.value.trim()) {
                personaInput.value = "文本40";
                personaInput.classList.add('special-text');

                personaInput.readOnly = true;
            }

            switchTab('levels');
        }

        async function loadSwipes() {
            const container = document.getElementById('swipe-list-container');
            try {
                if (typeof getChatMessages !== 'function') {
                    container.innerHTML = '<p style="color:red; text-align:center;">文本41</p>';
                    return;
                }
                const messages = await getChatMessages(0, { include_swipe: true });
                if (!messages || messages.length === 0) {
                    container.innerHTML = '<p style="text-align:center;">文本42: 文本43</p>';
                    return;
                }
                const swipes = messages[0].swipes || [messages[0].mes];

                if (swipes.length <= 1) {
                    container.innerHTML = `
                        <div style="text-align:center;">
                            <p style="color:#ff5555;">[ 文本44 ]</p>
                            <p>文本45</p>
                            <p style="font-size:12px; color:#aaa; margin-top:10px;">文本46<br>文本47</p>
                        </div>`;
                    return;
                }
                let html = '';
                for (let i = 1; i < swipes.length; i++) {
                    const content = swipes[i];
                    let title = `SCENARIO_FILE_0${i}`;
                    const titleMatch = content.match(/<!--\s*title:\s*(.*?)\s*-->/);
                    if (titleMatch && titleMatch[1]) { title = titleMatch[1].trim(); }

                    let preview = '<span class="loading-text">【 文本48 】</span>';
                    const summaryMatch = content.match(/<!--\s*(?:summary|desc|文本49):\s*(.*?)\s*-->/i);
                    if (summaryMatch && summaryMatch[1]) {
                        preview = summaryMatch[1].trim();
                    }

                    html += `<div class="list-item" onclick="selectScenario(${i})">
                            <div style="width: 100%;">
                                <span class="list-item-title">${title}</span>
                                <span class="list-item-preview">${preview}</span>
                            </div>
                        </div>`;
                }
                container.innerHTML = html;
            } catch (e) {
                console.error(e);
                container.innerHTML = '<p style="color:red; text-align:center;">文本50</p>';
            }
        }

        const loverInput = document.getElementById('user-lover');
        loverInput.addEventListener('focus', function() {
            this.value = "文本51".repeat(20);
            this.classList.add('triggered');
            this.readOnly = true;
            if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 文本52');
        });
        loverInput.addEventListener('click', function() { this.focus(); });

        function escapeSpecialChars(str) {
            if (typeof str !== 'string') return str;
            return str.replace(/\|/g, '\\|').replace(/"/g, '\\"');
        }

        function submitProfileForm() {
            const name = document.getElementById('user-name').value || "文本53";
            const desc = document.getElementById('user-desc').value || "文本54";


            let persona = document.getElementById('user-persona').value;


            const easterEggText = "文本40";
            if (persona.includes(easterEggText)) {
                persona = ""; 
            }


            const userData = {
                Player: name,
                Appearance: desc,
                Personality: persona,
                Status: "In_Game"
            };

            const jsonString = JSON.stringify(userData, null, 2);


            const wiFilename = "文本55";
            const wiUid = "2";


            return `/setentryfield file="${wiFilename}" uid=${wiUid} field=content ${escapeSpecialChars(jsonString)}`;
        }

        async function selectScenario(swipeIndex) {
            const container = document.getElementById('swipe-list-container');
            container.style.filter = "grayscale(100%)";
            container.innerHTML = '<p style="color:var(--neon-green); text-align:center;">文本56</p>';
            try {
                const wiCommand = submitProfileForm();

                if (typeof triggerSlash === 'function') {
                    await triggerSlash(`${wiCommand} | /echo severity=success 文本57...`);
                }
                if (typeof setChatMessages === 'function') {
                    setTimeout(async () => {
                        await setChatMessages([{ message_id: 0, swipe_id: swipeIndex }]);
                    }, 800);
                }
            } catch (error) {
                console.error(error);
                container.innerHTML = '<p style="color:red; text-align:center;">文本58</p>';
            }
        }
    </script>
</body>
</html>
