            if (!ctx) return;
            var parent = canvas.parentElement;
            function resize() { canvas.width = parent.clientWidth; canvas.height = parent.clientHeight; }
            resize();
            if(window.ResizeObserver) { new ResizeObserver(resize).observe(parent); }
            var particles = []; var maxParticles = 60;
            function initParticles() {
                particles = [];
                for (var i = 0; i < maxParticles; i++) {
                    particles.push({
                        x: Math.random() * canvas.width, y: Math.random() * canvas.height,
                        r: Math.random() * 2 + 1, d: Math.random() * maxParticles
                    });
                }
            }
            initParticles();
            function draw() {
                if(!document.body.contains(canvas)) return;
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
                ctx.beginPath();
                for (var i = 0; i < maxParticles; i++) {
                    var p = particles[i];
                    ctx.moveTo(p.x, p.y); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2, true);
                }
                ctx.fill(); update(); requestAnimationFrame(draw);
            }
            function update() {
                var globalAngle = Date.now() * 0.001;
                for (var i = 0; i < maxParticles; i++) {
                    var p = particles[i];
                    p.y += Math.cos(globalAngle + p.d) + 1 + p.r * 0.5;
                    p.x += Math.sin(globalAngle) * 1.5;
                    if (p.x > canvas.width + 5 || p.x < -5 || p.y > canvas.height) {
                        particles[i].x = Math.random() * canvas.width; particles[i].y = -10;
                    }
                }
            }
            requestAnimationFrame(draw);
        })();

