            if (texts.length === 0) return;
            const text = texts[Math.floor(Math.random() * texts.length)];
            const floating = document.createElement('div');
            floating.className = 'float-text';
            floating.innerText = "❤️ " + text;
            const rightOffset = Math.floor(Math.random() * 50);
            floating.style.right = rightOffset + 'px'; floating.style.left = 'auto';
            floating.style.top = (element.offsetTop - 25) + 'px';
            element.parentElement.appendChild(floating);
