    <script>
        const contentData = {
            countdown: '$1',
            note: '$5',
            status: '$3$4',
            items: '$2'
        };

        let currentPageIndex = 0;
        let pages = [];


        let easterEggState = 0; 

        function initPages() {
            const area = document.getElementById('handwritingArea');
            const areaHeight = area.clientHeight;

            const tempContainer = document.createElement('div');
            tempContainer.style.cssText = 'position:absolute;visibility:hidden;width:' + area.clientWidth + 'px;';
            document.body.appendChild(tempContainer);

            const elements = [
                { type: 'countdown', html: `<div class="countdown-handwritten">${contentData.countdown}</div>` },
                { type: 'note', html: `<div class="handwritten-text note-paragraph">${contentData.note}</div>` },
                { type: 'status', html: `<div class="handwritten-text status-paragraph">${contentData.status}</div>` },
                { type: 'items', html: `<div class="handwritten-text items-paragraph">${contentData.items}</div>` }
            ];

            pages = [];
            let currentPageContent = [];
            let currentHeight = 0;
            const maxHeight = areaHeight - 20;

            elements.forEach(elem => {
                tempContainer.innerHTML = elem.html;
                const elemHeight = tempContainer.firstChild.offsetHeight;

                if (currentHeight + elemHeight > maxHeight && currentPageContent.length > 0) {
                    pages.push(currentPageContent.join(''));
                    currentPageContent = [];
                    currentHeight = 0;
                }

                currentPageContent.push(elem.html);
                currentHeight += elemHeight + 22;
            });

            if (currentPageContent.length > 0) {
                pages.push(currentPageContent.join(''));
            }

            if (pages.length === 0) {
                pages.push(elements.map(e => e.html).join(''));
            }

            document.body.removeChild(tempContainer);

            document.getElementById('totalPages').textContent = pages.length;
            renderCurrentPage();
            updateNavButtons();
        }

        function renderCurrentPage() {
            const area = document.getElementById('handwritingArea');
            area.innerHTML = `<div class="page-content active">${pages[currentPageIndex]}</div>`;
            document.getElementById('currentPage').textContent = currentPageIndex + 1;
        }

        function updateNavButtons() {
            const prevBtn = document.getElementById('prevBtn');
            const nextBtn = document.getElementById('nextBtn');

            prevBtn.classList.toggle('disabled', currentPageIndex === 0);
            nextBtn.classList.toggle('disabled', currentPageIndex >= pages.length - 1);
        }

        function flipPage(direction) {
            const inner = document.getElementById('notebookInner');
            inner.classList.add('flipping');

            setTimeout(() => {
                if (direction === 'next' && currentPageIndex < pages.length - 1) {
                    currentPageIndex++;
                } else if (direction === 'prev' && currentPageIndex > 0) {
                    currentPageIndex--;
                }
                renderCurrentPage();
                updateNavButtons();

                inner.classList.remove('flipping');
                inner.classList.add('flipping-in');

                setTimeout(() => {
                    inner.classList.remove('flipping-in');
                }, 250);
            }, 250);
        }

        function nextPage() {
            if (currentPageIndex < pages.length - 1) {
                flipPage('next');
            }
        }

        function prevPage() {
            if (currentPageIndex > 0) {
                flipPage('prev');
            }
        }

        function openNotebook() {
            document.getElementById('monitorLog').classList.add('show-inner');
            setTimeout(initPages, 100);
        }

        function closeNotebook() {
            document.getElementById('monitorLog').classList.remove('show-inner');
            currentPageIndex = 0;
        }


        function advanceEasterEgg() {
            const lines = [
                document.getElementById('eggLine1'),
                document.getElementById('eggLine2'),
                document.getElementById('eggLine3'),
                document.getElementById('eggLine4')
            ];

            if (easterEggState < 4) {
                easterEggState++;


                lines.forEach((line, index) => {
                    const lineNum = index + 1;

                    if (lineNum < easterEggState) {

                        line.classList.add('revealed', 'smeared');
                    } else if (lineNum === easterEggState) {

                        line.classList.add('revealed');
                        line.classList.remove('smeared');
                    } else {

                        line.classList.remove('revealed', 'smeared');
                    }
                });
            }
        }


        document.addEventListener('DOMContentLoaded', function() {
            document.getElementById('totalPages').textContent = '1';

            const easterEggZone = document.getElementById('easterEggZone');
            easterEggZone.addEventListener('click', function(e) {
                e.stopPropagation();
                advanceEasterEgg();
            });
        });
    </script>

</body>
